  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-page:       #0f1117;
  --bg-card:       #1a1d27;
  --bg-input:      #12141e;
  --border-default: #2e3347;
  --border-focus:  #6c8fff;
  --border-error:  #f56565;
  --text-primary:  #e8eaf0;
  --text-secondary: #8b92a9;
  --text-placeholder: #4e5570;
  --accent:        #6c8fff;
  --accent-hover:  #5a7af0;
  --error:         #f56565;
  --success:       #48bb78;
  --radius:        8px;
  --transition:    0.18s ease;
}

body {
  background: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: 14px;
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}

.card-header {
  margin-bottom: 2rem;
}

.card-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.card-header p {
  margin-top: 0.4rem;
  font-size: 0.925rem;
  color: var(--text-secondary);
}

/* Form fields */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 1.25rem;
}

.form-field label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
}

.required-mark {
  color: var(--error);
  margin-left: 0.2em;
  aria-hidden: true;
}

.form-field input {
  background: var(--bg-input);
  border: 1.5px solid var(--border-default);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-family: inherit;
  font-size: 0.975rem;
  padding: 0.65rem 0.875rem;
  width: 100%;
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.form-field input::placeholder {
  color: var(--text-placeholder);
}

.form-field input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(108, 143, 255, 0.25);
  /* transparent outline for forced-colors */
  outline: 3px solid transparent;
}

.form-field input[aria-invalid="true"] {
  border-color: var(--border-error);
}

.form-field input[aria-invalid="true"]:focus {
  border-color: var(--border-error);
  box-shadow: 0 0 0 3px rgba(245, 101, 101, 0.25);
}

/* Helper / error text */
.helper-text,
.error-msg {
  font-size: 0.8125rem;
  line-height: 1.4;
}

.helper-text {
  color: var(--text-secondary);
}

.error-msg {
  color: var(--error);
  display: none;
}

.error-msg[aria-live] {
  display: block; /* always rendered; visibility toggled via content */
}

.form-field.has-error .error-msg {
  display: block;
}

/* Submit */
.form-actions {
  margin-top: 1.75rem;
}

.btn-submit {
  background: var(--accent);
  border: none;
  border-radius: var(--radius);
  color: #fff;
  cursor: pointer;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  width: 100%;
  transition: background var(--transition), box-shadow var(--transition);
  outline: none;
}

.btn-submit:hover {
  background: var(--accent-hover);
}

.btn-submit:focus-visible {
  box-shadow: 0 0 0 3px rgba(108, 143, 255, 0.4);
  outline: 3px solid transparent;
}

.btn-submit:active {
  background: #4a6ae0;
}

/* Status banner */
.status-banner {
  border-radius: var(--radius);
  font-size: 0.9rem;
  font-weight: 500;
  margin-bottom: 1.25rem;
  padding: 0.75rem 1rem;
  display: none;
}

.status-banner.success {
  background: rgba(72, 187, 120, 0.12);
  border: 1px solid var(--success);
  color: var(--success);
  display: block;
}

.status-banner.error {
  background: rgba(245, 101, 101, 0.1);
  border: 1px solid var(--error);
  color: var(--error);
  display: block;
}

/* Responsive reflow */
@media (max-width: 400px) {
  .card {
    padding: 1.5rem 1.1rem;
  }
}

/* Forced colors */
@media (forced-colors: active) {
  .form-field input:focus,
  .btn-submit:focus-visible {
    outline: 3px solid ButtonText;
  }
  .btn-submit {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonBorder;
  }
}
