        // Allow digits, spaces, hyphens, dots, parentheses, leading +
        if (!/^\+?[\d\s\-().]{7,20}$/.test(value.trim())) {
          return 'Please enter a valid phone number (e.g. +1 555-123-4567).';
        }
        return null;
      },
    },
  };

