      // Focus first invalid input
      const firstInvalidName = fields.find((n) => !results[fields.indexOf(n)]);
      if (firstInvalidName) {
        document.getElementById(firstInvalidName).focus();
      }
      statusBanner.textContent = 'Please correct the errors below before submitting.';
      statusBanner.classList.add('error');
      return;
    }

